{"query":"# Chips (and camera image sensors) with a die area in mm² on Wikidata
SELECT ?chip ?chipLabel ?area (GROUP_CONCAT(DISTINCT ?classLabel; separator=", ") AS ?classes)
       (SAMPLE(?nodeLabel) AS ?node) (SAMPLE(?mfrLabel) AS ?maker) (MIN(?date) AS ?released) (SAMPLE(?article) AS ?wikipedia)
WHERE {
  VALUES ?class { wd:Q122901167 wd:Q122760264 wd:Q2713403 wd:Q539558 wd:Q122760330 wd:Q122967152 wd:Q610398 wd:Q406283 wd:Q115722011 wd:Q10929058 }
  ?chip wdt:P31 ?class ; p:P2046/psv:P2046 [ wikibase:quantityAmount ?area ; wikibase:quantityUnit wd:Q2737347 ] .
  ?class rdfs:label ?classLabel . FILTER(LANG(?classLabel) = "en")
  OPTIONAL { ?chip wdt:P2079 ?n . ?n rdfs:label ?nodeLabel . FILTER(LANG(?nodeLabel) = "en") }
  OPTIONAL { ?chip wdt:P176 ?m . ?m rdfs:label ?mfrLabel . FILTER(LANG(?mfrLabel) = "en") }
  OPTIONAL { ?chip wdt:P577 ?date }
  OPTIONAL { ?article schema:about ?chip ; schema:isPartOf <https://en.wikipedia.org/> }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?chip ?chipLabel ?area
ORDER BY ?area","format":"json"}
